[SrsReportParameterAttribute(classStr(METCCRContract))]
public class METCCRDP extends SrsReportDataProviderPreProcessTempDB
{
    METCCRTableTmp ccrTableTmp;

}

Method.Source:
[SrsReportDataSetAttribute('METCCRTableTmp')]
public METCCRTableTmp getData()
{
    select * from ccrTableTmp;
    return ccrTableTmp;
}

public void processReport()
{
    METCCRTable metCCRTable;;

    while select metCCRTable
    {
        ccrTableTmp.clear();
        ccrTableTmp.ItemDescription = "";
        ccrTableTmp.ItemId = "";
        ccrTableTmp.CustAddress = "";
        ccrTableTmp.CustId = "";
        ccrTableTmp.QtyPlaced = 0.00;
        ccrTableTmp.TimeStamp = DateTimeUtil::utcNow();
        ccrTableTmp.UOM = "";
        ccrTableTmp.TotalCartoons =0.00;
        ccrTableTmp.ToteId = "";
        ccrTableTmp.insert();

    }
}
